"""Assemble review HTML; original reference files remain unchanged."""
from pathlib import Path
root=Path('artifacts/athlete-review')
views=[('flight-side','Lot — bok'),('flight-front','Lot — przód'),('flight-top','Lot — góra'),('flight-quarter','Lot — 3/4'),('inrun','Najazd'),('extension','Wyprost'),('flight-020','0,2 s'),('flight-050','0,5 s'),('telemark','Telemark'),('neutral-front','Neutralna — przód'),('neutral-side','Neutralna — bok'),('neutral-back','Neutralna — tył'),('neutral-quarter','Neutralna — 3/4')]
refs=[('01_prevc_flight_side.jpg','reference-prevc','Peter Prevc — Wladyslaw Sojka / Taxiarchos228, FAL'),('02_v_front.jpg','reference-front','Lot z przodu — Sandro Halank, CC BY-SA 4.0'),('03_hvala_threequarter.jpg','flight-quarter','Jaka Hvala — Bjoertvedt, CC BY-SA 3.0'),('04_schmitt_front_threequarter.jpg','flight-front','Thorsten Schmitt — Alexander Nilssen, CC BY-SA 2.0'),('05_stoch_telemark.jpg','telemark','Kamil Stoch — Christian Bier, CC BY-SA 4.0')]
html='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>SKYLIFT — przegląd zawodnika GLB</title><style>body{font:16px system-ui;background:#15232c;color:#eff3f5;margin:0;padding:28px;max-width:1500px;margin:auto}h1{font-size:32px}h2{margin-top:48px}p{max-width:900px;line-height:1.6;color:#c5d3dd}.pair{display:grid;grid-template-columns:1fr 1fr;gap:14px}figure{margin:0;background:#dce3e8;border-radius:8px;overflow:hidden}img{display:block;width:100%;height:430px;object-fit:contain}figcaption{padding:12px;background:#233744}a{color:#9ddbea}@media(max-width:700px){body{padding:12px}.pair{grid-template-columns:1fr}img{height:auto}}</style><h1>SKYLIFT · zawodnik ze szkieletem GLB</h1><p>Porównania PRZED/PO: ta sama kamera, skala i stan kontrolera. Oryginalna, ciągła siatka kombinezonu z Blendera, 19 kości; fizyka nart i wiązań zachowana. Poniżej także porównania z pięcioma dostarczonymi fotografiami.</p>'''
for stem,label in views:
 html+=f'<h2>{label}</h2><div class="pair">'+''.join(f'<figure><img loading="lazy" src="{phase}/{stem}.png"><figcaption>{caption}</figcaption></figure>' for phase,caption in [('before','PRZED'),('after','PO')])+'</div>'
html+='<h2>Referencje fotograficzne</h2><p>Kierunki kamer są przybliżone. Fotografie nie są kalibracją kątów ani pomiarem biomechanicznym. Obrazy źródłowe pozostają niezmienione i nie są teksturami gry. <a href="../../references/athlete/README.md">Autorzy, źródła i pełne odnośniki do licencji</a>.</p>'
for file,stem,credit in refs:
 html+=f'<h2>{credit}</h2><div class="pair"><figure><img loading="lazy" src="../../references/athlete/{file}"><figcaption>Fotografia referencyjna · {credit}</figcaption></figure><figure><img loading="lazy" src="after/{stem}.png"><figcaption>Render GLB · przybliżony kierunek kamery</figcaption></figure></div>'
(root/'index.html').write_text(html)
